import json,subprocess,datetime
d=json.load(open('/tmp/r.json'))
u=lambda m:datetime.datetime.fromtimestamp(m/1000,datetime.timezone.utc).strftime('%m-%d %H:%M')
c=[]
for k,a in d['accounts'].items():
  for t in a.get('trades',[]):
    if t.get('run') is not None and not t['open']: c.append((k,t))
c.sort(key=lambda z:z[1]['t_in'])
print(len(c))
for k,t in [c[0],c[-1]] if c else []:
  o=subprocess.run(['curl','-s','localhost:8091/api/prop_chart?run=%d&t_in=%d&side=%s'%(t['run'],t['kt'] if 'kt' in t else t['t_in'],t['side'])],capture_output=True,text=True).stdout
  try:
    D=json.loads(o);ch=D['chart'];print(k,t['sym'],t['tf'],u(t['t_in']),'n',len(ch['t']),u(ch['t'][0]),u(ch['t'][-1]),'off',D['off'],'out',u(D['t_out']),D['reason'],'ch',D['ch'] is not None)
  except Exception as e: print(k,t['sym'],o[:200])
